// Helper CSV parser that handles quotes and newlines
function parseCSV(text) {
  const lines = [];
  let row = [];
  let inQuotes = false;
  let currentVal = '';

  for (let i = 0; i < text.length; i++) {
    const char = text[i];
    const nextChar = text[i + 1];

    if (char === '"') {
      if (inQuotes && nextChar === '"') {
        currentVal += '"';
        i++;
      } else {
        inQuotes = !inQuotes;
      }
    } else if (char === ',' && !inQuotes) {
      row.push(currentVal.trim());
      currentVal = '';
    } else if ((char === '\r' || char === '\n') && !inQuotes) {
      if (char === '\r' && nextChar === '\n') {
        i++;
      }
      row.push(currentVal.trim());
      if (row.length > 1 || row[0] !== '') {
        lines.push(row);
      }
      row = [];
      currentVal = '';
    } else {
      currentVal += char;
    }
  }
  if (currentVal || row.length > 0) {
    row.push(currentVal.trim());
    lines.push(row);
  }
  return lines;
}

const parsed = parseCSV(rawData);
const header = parsed[0];
const rows = parsed.slice(1);

const billingEntries = [];
const clientUrls = {};

rows.forEach((r, idx) => {
  const teId = r[0];
  const institutionName = r[1];
  const clientName = r[2] || institutionName;
  const contact = r[3];
  const operatorContact = r[4];
  const studentCount = parseInt(r[5] || '0', 10) || 0;
  const purchaseDate = r[6] || '';
  const purchaseBy = r[7] || '';
  const department = r[8] || 'TaleemPro';
  const plan = r[9] || 'Basic';
  const billingType = r[10] || 'Full Paid';
  const setupAmount = parseFloat((r[11] || '0').replace(/[^0-9.-]/g, '')) || 0;
  const setupPaid = parseFloat((r[12] || '0').replace(/[^0-9.-]/g, '')) || 0;
  const setupRemaining = parseFloat((r[13] || '0').replace(/[^0-9.-]/g, '')) || 0;
  const monthlySubscription = parseFloat((r[14] || '0').replace(/[^0-9.-]/g, '')) || 0;
  const dueFromDate = r[15] || '';
  const monthsDue = parseInt(r[16] || '0', 10) || 0;
  const subscriptionDue = parseFloat((r[17] || '0').replace(/[^0-9.-]/g, '')) || 0;
  const totalSubPaid = parseFloat((r[18] || '0').replace(/[^0-9.-]/g, '')) || 0;
  const totalOutstanding = parseFloat((r[19] || '0').replace(/[^0-9.-]/g, '')) || 0;
  const lastPaymentDate = r[20] || '';
  const paymentStatusRaw = r[21] || 'Paid';
  const paymentStatus = paymentStatusRaw.includes('Overdue') ? 'Overdue' : 'Paid';
  const relationshipValue = r[22] || 'Normal';
  const loginUrl = r[23] || '';
  const loginId = r[24] || '';
  const loginPassword = r[25] || '';
  const assignedExecutive = r[29] || 'Umar Farooq';
  const currentStatus = r[33] || 'Connected';
  const softwareUsage = r[34] || 'Regular User';
  const satisfactionStatus = r[37] || 'Working & Happy';

  if (!teId || !institutionName || teId.toLowerCase() === 'coo') return;

  const entry = {
    id: `bil-${teId}`,
    teId: teId,
    clientName: institutionName,
    department: department,
    softwareUrl: loginUrl.startsWith('http') ? loginUrl : (loginUrl ? `https://${loginUrl}` : ''),
    plan: plan,
    studentCount: studentCount,
    storageUsageGb: Math.round((studentCount * 0.05 + 1.2) * 10) / 10,
    billingFrequency: monthlySubscription >= 800 ? 'Yearly' : 'Monthly',
    amcAmount: monthlySubscription * 12 || setupAmount || 5000,
    monthlySubscription: monthlySubscription,
    setupAmount: setupAmount,
    setupPaid: setupPaid,
    setupRemaining: setupRemaining,
    monthsDue: monthsDue,
    subscriptionDue: subscriptionDue,
    totalOutstanding: totalOutstanding,
    paymentStatus: paymentStatus,
    lastPaymentDate: lastPaymentDate,
    nextRenewalDate: dueFromDate || '2026-12-31',
    operationsStatus: currentStatus === 'Connected' || currentStatus === 'Completed' ? 'Active' : 'On Trial',
    activeModules: ['Attendance', 'Fees', 'Exams', 'Accounts', 'User Management'],
    softwareLoginId: loginId,
    softwarePassword: loginPassword,
    assignedExecutive: assignedExecutive,
    remarks: r[40] || r[41] || r[30] || '',
    updatedAt: new Date().toISOString()
  };

  billingEntries.push(entry);

  if (loginUrl) {
    clientUrls[teId] = {
      url: entry.softwareUrl,
      login: loginId,
      password: loginPassword,
      remarks: entry.remarks
    };
  }
});

const outPath = path.join(process.cwd(), 'data', 'client_usage_billing.json');
fs.writeFileSync(outPath, JSON.stringify(billingEntries, null, 2), 'utf-8');
console.log(`Saved ${billingEntries.length} billing entries to ${outPath}`);

// Update data/client_urls.json as well
const clientUrlsPath = path.join(process.cwd(), 'data', 'client_urls.json');
let existingUrls = {};
try {
  if (fs.existsSync(clientUrlsPath)) {
    existingUrls = JSON.parse(fs.readFileSync(clientUrlsPath, 'utf-8'));
  }
} catch (e) {}

const mergedUrls = { ...existingUrls, ...clientUrls };
fs.writeFileSync(clientUrlsPath, JSON.stringify(mergedUrls, null, 2), 'utf-8');
console.log(`Updated client_urls.json with ${Object.keys(mergedUrls).length} clients`);
